console.log(NaN === NaN); // false - NaN nie jest rowny SAMEMU SOBIE

function jestNaN(wartosc) {
  return Number.isNaN(wartosc);
}

jestNaN(0 / "tekst"); // true
jestNaN(42); // false

function porownajScisle(a, b) {
  return a === b;
}

porownajScisle(5, 5);     // true
porownajScisle(5, "5");   // false
porownajScisle("a", "a"); // true

function jestPusteLubBrak(wartosc) {
  return wartosc == null;
}

jestPusteLubBrak(null);      // true
jestPusteLubBrak(undefined); // true
jestPusteLubBrak(0);         // false
jestPusteLubBrak("");        // false

function jestPusteLubBrakScisle(wartosc) {
  return wartosc === null || wartosc === undefined;
}

jestPusteLubBrakScisle(null);      // true
jestPusteLubBrakScisle(undefined); // true
jestPusteLubBrakScisle(0);         // false

const idZAPI = "42";
const szukaneId = 42;

if (Number(idZAPI) === szukaneId) {
  console.log("Znaleziono");
}
// "Znaleziono" - konwersja jawna, kontrolowana, zamiast ukrytej w ==

// === jest ZAWSZE przewidywalne - porownuje wartosc I typ, bez ukrytej
// konwersji. == wykonuje NIEJAWNA konwersje typow PRZED porownaniem, co
// prowadzi do zaskakujacych, nieintuicyjnych wynikow, np.:
// 1. 0 == false -> true (false konwertowane do 0, mimo ze to zupelnie
//    rozne koncepcyjnie wartosci - liczba i wartosc logiczna)
// 2. [] == false -> true (pusta tablica konwertowana najpierw do stringa
//    "", potem do liczby 0, a nastepnie porownywana z 0) - bardzo trudne
//    do przewidzenia bez znajomosci dokladnych regul konwersji
// Dlatego === jest bezpiecznym domyslnym wyborem - eliminuje cala klase
// bledow wynikajacych z nieoczekiwanej, ukrytej konwersji typow.
